def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set(); objs = []
    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if not col or (r,c) in seen: continue
            cells={(r,c)}; seen.add((r,c)); q=[(r,c)]
            while q:
                y,x=q.pop()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==col:
                        seen.add(p); cells.add(p); q.append(p)
            minr=min(y for y,x in cells); maxr=max(y for y,x in cells)
            minc=min(x for y,x in cells); maxc=max(x for y,x in cells)
            exterior=set(); q=deque()
            for y in range(minr,maxr+1):
                for x in range(minc,maxc+1):
                    if (y in (minr,maxr) or x in (minc,maxc)) and (y,x) not in cells and (y,x) not in exterior:
                        exterior.add((y,x)); q.append((y,x))
            while q:
                y,x=q.popleft()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if minr<=p[0]<=maxr and minc<=p[1]<=maxc and p not in cells and p not in exterior:
                        exterior.add(p); q.append(p)
            hole=any((y,x) not in cells and (y,x) not in exterior for y in range(minr,maxr+1) for x in range(minc,maxc+1))
            objs.append({'col':col,'cells':cells,'top':minr,'bottom':maxr,'hole':hole,'shift':0})
    # Objects with enclosed holes rise; the others fall. Process the leading
    # objects first so that following objects settle against them.
    for direction in ('up','down'):
        group=[o for o in objs if o['hole']==(direction=='up')]
        group.sort(key=lambda o:o['top'] if direction=='up' else -o['bottom'])
        settled=[]
        for o in group:
            step=-1 if direction=='up' else 1
            while True:
                moved={(r+o['shift']+step,c) for r,c in o['cells']}
                if any(r<0 or r>=h for r,c in moved): break
                if any(moved & {(r+p['shift'],c) for r,c in p['cells']} for p in settled): break
                o['shift']+=step
            settled.append(o)
    out=[[0]*w for _ in range(h)]
    for o in objs:
        for r,c in o['cells']:
            out[r+o['shift']][c]=o['col']
    return out
